const PD = (gdjs.PD = gdjs.PD || {});
if (!PD.refreshHud) {
  PD.setText = function (S, name, text) {
    const o = S.scene.getObjects(name)[0];
    if (o) o.setText(text);
  };
  PD.banner = (S, text) => PD.setText(S, 'Txt_Banner', text);

  // Right panel orb queue: in battle the big icon is the next orb and the row is what follows;
  // between fights the row is the whole bag.
  PD.refreshOrbQueue = function (S) {
    const run = S.run;
    for (const o of S.hudIcons || []) o.deleteFromScene();
    S.hudIcons = [];
    const prev = S.scene.getObjects('Orb_Preview')[0];
    const add = (orb, x, y, size) => {
      const i = S.scene.createObject('Map_Icon');
      i.setAnimationName('Orb' + orb.type);
      i.setSize(size, size);
      i.setPosition(x, y);
      i.setZOrder(11);
      S.hudIcons.push(i);
      if (orb.lvl > 1) {
        const t = PD.label(S, '' + orb.lvl, x + size - 10, y + size - 12, 14, 11, '255;215;0', 12);
        S.screen.pop();
        S.hudIcons.push(t);
      }
    };
    const row = (orbs, y) => {
      orbs.slice(0, 16).forEach((o, k) => add(o, 1007 + (k % 8) * 30, y + Math.floor(k / 8) * 30, 26));
      if (orbs.length > 16) {
        const t = PD.label(S, '+' + (orbs.length - 16), 1007, y + 62, 60, 12, '192;208;232', 12, 'left');
        S.screen.pop();
        S.hudIcons.push(t);
      }
    };
    if (S.current && (S.state === 'aim' || S.state === 'drop' || S.state === 'resolve')) {
      const st = PD.orbStats(S, S.current);
      PD.setText(S, 'Txt_OrbInfo', 'NEXT ORB: ' + st.name + ' LV' + S.current.lvl + '\nBASE ' + st.base + ' · +' + st.perPeg + ' PER PEG');
      if (prev) { prev.hide(false); prev.setAnimation(st.anim); }
      const upcoming = run.draw.slice().reverse();
      const t = PD.label(S, upcoming.length ? 'THEN:' : 'THEN: BAG RESHUFFLES', 1007, 452, 240, 11, '150;165;190', 12, 'left');
      S.screen.pop();
      S.hudIcons.push(t);
      row(upcoming.length ? upcoming : run.bag, 470);
      if (!upcoming.length) for (const i of S.hudIcons) if (i.getName() === 'Map_Icon') i.setOpacity(110);
    } else {
      PD.setText(S, 'Txt_OrbInfo', 'ORB BAG (' + run.bag.length + ')\nEach drop uses the next orb.\nThe bag reshuffles when empty.');
      if (prev) prev.hide(true);
      row(run.bag, 405);
    }
  };

  PD.refreshHud = function (S) {
    const run = S.run, e = S.enemy;
    if (!run) return;
    PD.setText(S, 'Txt_Subtitle', 'ACT ' + (run.act + 1) + ': ' + PD.ACT_NAMES[run.act % 3]);
    PD.setText(S, 'Txt_Round', 'FLOOR ' + run.floor + '  ·  ACT ' + (run.act + 1));
    PD.setText(S, 'Txt_PlayerHP_Label', 'HP: ' + Math.max(0, run.hp) + ' / ' + run.maxHp);
    PD.setText(S, 'Txt_PlayerChips', '$ ' + run.chips);
    const broke = run.chips < PD.ANTE;
    PD.setText(S, 'Txt_Ante', broke ? 'BROKE: FREE DROP' : 'ANTE $10 [1]' + (run.wager === PD.ANTE ? ' (ON)' : ''));
    PD.setText(S, 'Txt_HighRoller', 'HIGH ROLLER $25 [2]' + (run.wager === PD.HIGH_ROLLER ? ' (ON)' : ''));
    const hearts = S.scene.getObjects('UI_Heart');
    hearts.forEach((h, i) => h.setOpacity(run.hp > (i * run.maxHp) / hearts.length ? 255 : 60));
    PD.refreshOrbQueue(S);
    const relicNames = run.relics.map((id) => PD.RELICS.find((r) => r.id === id).name);
    PD.setText(S, 'Txt_Controls', 'RELICS (' + relicNames.length + ')\n' + (relicNames.join(', ') || 'none yet') + '\n\n[M] MUTE');
    if (e) {
      PD.setText(S, 'Txt_BossName', e.name);
      PD.setText(S, 'Txt_BossHP', 'HP: ' + e.hp + ' / ' + e.maxHp);
      PD.setText(S, 'Txt_BossCounter', 'ATTACK ' + e.atk + (PD.traitText(e) ? '\n' + PD.traitText(e) : ''));
      const fill = S.scene.getObjects('UI_HP_Fill')[0];
      if (fill) fill.setWidth(Math.max(0, (196 * e.hp) / e.maxHp));
    }
    if (S.state === 'map' || S.state === 'cards') PD.setText(S, 'Txt_BossName', S.state === 'map' ? 'THE MAP' : '');
  };
}

const PD = (gdjs.PD = gdjs.PD || {});
{
  if (!runtimeScene.__pd) {
    const S = (runtimeScene.__pd = { scene: runtimeScene, screen: [], mapIcons: [], popups: [], time: 0, cooldown: 0, shake: 0, enemyFlash: 0, playerFlash: 0, bossLunge: 0, muted: false });
    S.mapPainter = runtimeScene.createObject('Ui_Painter');
